// pages/InputLeadsPage.jsx (Fixed - All bugs resolved)
import React, {
  useState,
  useRef,
  useEffect,
  useCallback,
  useMemo,
} from "react";
import {
  Box,
  Typography,
  Button,
  Card,
  Stack,
  MenuItem,
  Select,
  FormControl,
  Grid,
  Input,
  IconButton,
  Snackbar,
  Alert,
  CircularProgress,
  useMediaQuery,
  useTheme,
  AlertTitle,
  Avatar,
  alpha,
  Paper,
  InputLabel,
  Badge,
  Fade,
  Zoom,
  Fab,
  BottomNavigation,
  BottomNavigationAction,
  Tooltip,
  Divider,
  Skeleton,
  Chip,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Menu,
} from "@mui/material";
import {
  Add,
  Description,
  Close,
  FilterList,
  Upload,
  CloudUpload,
  Download,
  People,
  TrendingUp,
  Warning,
  Refresh,
  Dashboard,
  Person,
  Schedule,
  DateRange,
  FilterAlt,
  Clear,
  Info,
  CheckCircle,
  Error,
  FileDownload,
  InsertDriveFile,
  TableChart,
  BarChart,
  Assessment,
  FileCopy,
  DownloadForOffline,
  PictureAsPdf,
  TableRows,
} from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import { API_BASE_URL } from "../utils/apiConfig";

const PRIMARY = "#0f1f3d";
const SECONDARY = "#1a237e";
const SUCCESS = "#22c55e";
const WARNING = "#f59e0b";
const API_BASE = API_BASE_URL;

// Role-based access control
const ALLOWED_ROLES = ["Incharge", "ZSM", "Admin_panel", "TEAM"];

const hasAccess = (userRole) => ALLOWED_ROLES.includes(userRole);

// Role Configuration
const ROLE_CONFIG = {
  Admin_panel: {
    label: "Admin Panel",
    color: PRIMARY,
    icon: <Person sx={{ fontSize: 16 }} />,
  },
  ZSM: {
    label: "Operation Lead",
    color: PRIMARY,
    icon: <Person sx={{ fontSize: 16 }} />,
  },
  Incharge: {
    label: "Installer",
    color: PRIMARY,
    icon: <Person sx={{ fontSize: 16 }} />,
  },
  TEAM: {
    label: "Installer",
    color: PRIMARY,
    icon: <Person sx={{ fontSize: 16 }} />,
  },
};

const getRoleConfig = (role) => {
  return (
    ROLE_CONFIG[role] || {
      label: role || "User",
      color: PRIMARY,
      icon: <Person sx={{ fontSize: 16 }} />,
    }
  );
};

// Summary Card Component
const SummaryCard = ({ card, index }) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const displayColor = card.color;

  return (
    <Fade in={true} timeout={500 + index * 100}>
      <Paper
        elevation={0}
        sx={{
          p: { xs: 1.5, sm: 2, md: 2.5 },
          borderRadius: 3,
          bgcolor: isDark ? "#0b0e1a" : "#fff",
          color: isDark ? "#f8fafc" : "inherit",
          border: isDark ? `1px solid ${alpha(card.color, 0.25)}` : `1px solid ${alpha(card.color, 0.15)}`,
          boxShadow: isDark ? `0 4px 20px ${alpha(card.color, 0.15)}` : "0 4px 12px rgba(0,0,0,0.05)",
          transition: "transform 0.2s, box-shadow 0.2s",
          "&:hover": {
            transform: "translateY(-2px)",
            boxShadow: isDark ? `0 8px 28px ${alpha(card.color, 0.25)}` : "0 8px 24px rgba(0,0,0,0.1)",
          },
        }}
      >
        <Stack spacing={1}>
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <Box
              sx={{
                width: { xs: 32, sm: 40, md: 48 },
                height: { xs: 32, sm: 40, md: 48 },
                borderRadius: { xs: 1.5, sm: 2 },
                bgcolor: isDark ? alpha(displayColor, 0.2) : alpha(card.color, 0.1),
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: displayColor,
              }}
            >
              {React.cloneElement(card.icon, {
                sx: { fontSize: { xs: 16, sm: 20, md: 24 } },
              })}
            </Box>
            <Typography
              variant="h4"
              fontWeight={700}
              sx={{
                color: displayColor,
                fontSize: { xs: "1.25rem", sm: "1.5rem", md: "2rem" },
              }}
            >
              {card.value}
            </Typography>
          </Box>
          <Box>
            <Typography
              variant="subtitle2"
              fontWeight={600}
              color={isDark ? "#f8fafc" : "text.primary"}
              sx={{ fontSize: { xs: "0.75rem", sm: "0.875rem" } }}
            >
              {card.label}
            </Typography>
            <Typography
              variant="caption"
              color={isDark ? "#94a3b8" : "text.secondary"}
              sx={{ fontSize: { xs: "0.6rem", sm: "0.7rem" } }}
            >
              {card.subText}
            </Typography>
          </Box>
          <Typography
            variant="caption"
            sx={{
              color: displayColor,
              fontWeight: 500,
              display: "block",
              fontSize: { xs: "0.6rem", sm: "0.7rem" },
            }}
          >
            {card.trend}
          </Typography>
        </Stack>
      </Paper>
    </Fade>
  );
};

// Mobile Option Card Component
const MobileOptionCard = ({
  icon,
  title,
  description,
  buttonText,
  onClick,
  color = PRIMARY,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const displayColor = isDark && color === PRIMARY ? "#60a5fa" : color;

  return (
    <Paper
      elevation={0}
      sx={{
        p: 2.5,
        borderRadius: 3,
        border: `2px dashed ${isDark ? "rgba(96,165,250,0.3)" : alpha(color, 0.3)}`,
        bgcolor: isDark ? "#0e1220" : alpha(color, 0.02),
        color: isDark ? "#f8fafc" : "inherit",
        textAlign: "center",
      }}
    >
      <Avatar
        sx={{
          width: 56,
          height: 56,
          bgcolor: isDark ? "rgba(96,165,250,0.15)" : alpha(color, 0.1),
          color: displayColor,
          mx: "auto",
          mb: 2,
        }}
      >
        {icon}
      </Avatar>
      <Typography variant="h6" fontWeight={600} color={isDark ? "#f8fafc" : "text.primary"} gutterBottom>
        {title}
      </Typography>
      <Typography variant="body2" color={isDark ? "#94a3b8" : "text.secondary"} sx={{ mb: 2.5 }}>
        {description}
      </Typography>
      <Button
        onClick={onClick}
        variant="contained"
        startIcon={icon}
        fullWidth
        sx={{
          bgcolor: isDark ? "#3b82f6" : color,
          borderRadius: 2,
          py: 1.2,
          "&:hover": { bgcolor: SECONDARY },
        }}
      >
        {buttonText}
      </Button>
    </Paper>
  );
};

// Template Download Component
const TemplateDownload = ({ onDownload }) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);

  const handleClick = (event) => setAnchorEl(event.currentTarget);
  const handleClose = () => setAnchorEl(null);

  return (
    <>
      <Button
        onClick={handleClick}
        variant="outlined"
        startIcon={<FileDownload />}
        sx={{
          borderRadius: 2,
          borderColor: isDark ? "rgba(255,255,255,0.2)" : alpha(PRIMARY, 0.5),
          color: isDark ? "#60a5fa" : PRIMARY,
          "&:hover": {
            borderColor: isDark ? "#60a5fa" : PRIMARY,
            bgcolor: isDark ? "rgba(255,255,255,0.05)" : alpha(PRIMARY, 0.05),
          },
        }}
      >
        Download Template
      </Button>

      <Menu
        anchorEl={anchorEl}
        open={open}
        onClose={handleClose}
        PaperProps={{
          sx: {
            mt: 1.5,
            borderRadius: 2,
            minWidth: 200,
            bgcolor: isDark ? "#0b0e1a" : "#fff",
            color: isDark ? "#f8fafc" : "inherit",
            border: isDark ? "1px solid rgba(255,255,255,0.08)" : undefined,
            boxShadow: isDark ? "0 8px 24px rgba(0,0,0,0.5)" : "0 4px 20px rgba(0,0,0,0.1)",
          }
        }}
      >
        <MenuItem onClick={() => onDownload('csv')}>
          <ListItemIcon>
            <TableRows fontSize="small" sx={{ color: SUCCESS }} />
          </ListItemIcon>
          <ListItemText 
            primary={<Typography color={isDark ? "#f8fafc" : "inherit"}>CSV Template</Typography>} 
            secondary={<Typography variant="caption" color={isDark ? "#94a3b8" : "text.secondary"}>Simple format</Typography>} 
          />
        </MenuItem>
        <MenuItem onClick={() => onDownload('excel')}>
          <ListItemIcon>
            <TableChart fontSize="small" sx={{ color: isDark ? "#60a5fa" : PRIMARY }} />
          </ListItemIcon>
          <ListItemText 
            primary={<Typography color={isDark ? "#f8fafc" : "inherit"}>Excel Template</Typography>} 
            secondary={<Typography variant="caption" color={isDark ? "#94a3b8" : "text.secondary"}>With formatting</Typography>} 
          />
        </MenuItem>
        <MenuItem onClick={() => onDownload('sample')}>
          <ListItemIcon>
            <FileCopy fontSize="small" sx={{ color: WARNING }} />
          </ListItemIcon>
          <ListItemText 
            primary={<Typography color={isDark ? "#f8fafc" : "inherit"}>Sample Data</Typography>} 
            secondary={<Typography variant="caption" color={isDark ? "#94a3b8" : "text.secondary"}>With example entries</Typography>} 
          />
        </MenuItem>
      </Menu>
    </>
  );
};

export default function InputLeadsPage() {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const [filter, setFilter] = useState("Today");
  const [selectedFile, setSelectedFile] = useState(null);
  const [leadsData, setLeadsData] = useState({
    totalLeads: 0,
    activeLeads: 0,
    convertedLeads: 0,
    conversionRate: 0,
    todayLeads: 0,
    thisWeekLeads: 0,
    thisMonthLeads: 0,
  });
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const fileInputRef = useRef(null);
  const navigate = useNavigate();
  const { fetchAPI, getUserRole } = useAuth();
  const userRole = getUserRole();

  // Responsive breakpoints
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const isTablet = useMediaQuery(theme.breakpoints.down("md"));

  // Check access
  const canImportLeads = hasAccess(userRole);

  // Show snackbar helper - Define this FIRST before any function that uses it
  const showSnackbar = useCallback((message, severity = "success") => {
    setSnackbar({ open: true, message, severity });
  }, []);

  // Handle close snackbar
  const handleCloseSnackbar = useCallback(() => {
    setSnackbar((prev) => ({ ...prev, open: false }));
  }, []);

  // Stats cards data - memoized
  const statsCards = useMemo(
    () => [
      {
        label: "Total Leads",
        value: leadsData.totalLeads,
        color: "#3b82f6",
        icon: <People />,
        subText: "All time leads",
        trend:
          leadsData.todayLeads > 0
            ? `+${leadsData.todayLeads} today`
            : "No new leads",
      },
      {
        label: "Active Leads",
        value: leadsData.activeLeads,
        color: "#f59e0b",
        icon: <TrendingUp />,
        subText: "Currently active",
        trend: "Follow up required",
      },
      {
        label: "Converted",
        value: leadsData.convertedLeads,
        color: "#10b981",
        icon: <CheckCircle />,
        subText: "Successfully converted",
        trend: `${leadsData.conversionRate}% rate`,
      },
      {
        label: "This Month",
        value: leadsData.thisMonthLeads,
        color: "#a855f7",
        icon: <BarChart />,
        subText: "Monthly performance",
        trend:
          leadsData.thisWeekLeads > 0
            ? `+${leadsData.thisWeekLeads} this week`
            : "No weekly leads",
      },
    ],
    [leadsData],
  );

  // Fetch leads stats - optimized
  const fetchLeadsStats = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetchAPI("/lead/stats");

      if (response?.success && response.result?.stats) {
        setLeadsData({
          totalLeads: response.result.stats.totalLeads || 0,
          activeLeads: response.result.stats.activeLeads || 0,
          convertedLeads: response.result.stats.convertedLeads || 0,
          conversionRate: response.result.stats.conversionRate || 0,
          todayLeads: response.result.stats.todayLeads || 0,
          thisWeekLeads: response.result.stats.thisWeekLeads || 0,
          thisMonthLeads: response.result.stats.thisMonthLeads || 0,
        });
      } else {
        throw new Error(response?.message || "Failed to fetch leads stats");
      }
    } catch (error) {
      console.error("Error fetching leads stats:", error);
      showSnackbar("Failed to load leads statistics", "error");
      setLeadsData({
        totalLeads: 0,
        activeLeads: 0,
        convertedLeads: 0,
        conversionRate: 0,
        todayLeads: 0,
        thisWeekLeads: 0,
        thisMonthLeads: 0,
      });
    } finally {
      setLoading(false);
    }
  }, [fetchAPI, showSnackbar]);

  // Initial load
  useEffect(() => {
    if (canImportLeads) {
      fetchLeadsStats();
    }
  }, [fetchLeadsStats, canImportLeads]);

  // File validation helper
  const validateFile = useCallback((file) => {
    const allowedTypes = [".xlsx", ".csv"];
    const ext = "." + file.name.split(".").pop().toLowerCase();

    if (!allowedTypes.includes(ext)) {
      throw new Error(`Only ${allowedTypes.join(", ")} files are allowed`);
    }

    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      throw new Error("File size must be less than 10MB");
    }

    return true;
  }, []);

  // Handle file change
  const handleFileChange = useCallback(
    (e) => {
      if (!canImportLeads) {
        showSnackbar("You don't have permission to import leads", "error");
        return;
      }

      const file = e.target.files[0];
      if (!file) return;

      try {
        validateFile(file);
        setSelectedFile(file);
        showSnackbar(`Selected: ${file.name}`, "success");
      } catch (error) {
        showSnackbar(error.message, "error");
        e.target.value = null;
      }
    },
    [validateFile, canImportLeads, showSnackbar],
  );

  // Import leads function
  const handleImportLeads = useCallback(async () => {
    if (!canImportLeads) {
      showSnackbar("You don't have permission to import leads", "error");
      return;
    }

    if (!selectedFile) {
      showSnackbar("Please select a file first", "warning");
      return;
    }

    setUploading(true);
    const token = localStorage.getItem("token");

    try {
      const formData = new FormData();
      formData.append("file", selectedFile);
      formData.append("uploadedBy", userRole || "Unknown");

      const response = await fetch(`${API_BASE}/lead/import`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: formData,
      });

      const text = await response.text();

      // Check for HTML response (auth error)
      if (text.trimStart().startsWith("<!DOCTYPE") || text.includes("<html")) {
        throw new Error("Authentication failed. Please log in again.");
      }

      let data;
      try {
        data = JSON.parse(text);
      } catch {
        throw new Error("Invalid response from server");
      }

      if (!response.ok) {
        throw new Error(data.message || data.error || "Import failed");
      }

      showSnackbar(data.message || "Leads imported successfully!", "success");
      setSelectedFile(null);
      if (fileInputRef.current) fileInputRef.current.value = null;
      fetchLeadsStats(); // Refresh stats
    } catch (error) {
      console.error("Import error:", error);
      showSnackbar(error.message || "Failed to import leads", "error");
    } finally {
      setUploading(false);
    }
  }, [selectedFile, fetchLeadsStats, canImportLeads, userRole, showSnackbar]);

  // Generate dummy CSV content
  const generateDummyCSV = useCallback((type = 'csv') => {
    // Headers for the CSV
    const headers = [
      'name',
      'phone',
      'email',
      'source',
      'status',
      'address',
      'city',
      'state',
      'pincode',
      'notes'
    ].join(',');

    // Sample data rows
    const sampleData = [
      ['John Doe', '9876543210', 'john.doe@email.com', 'Website', 'new', '123 Main St', 'Mumbai', 'Maharashtra', '400001', 'Interested in premium package'],
      ['Jane Smith', '8765432109', 'jane.smith@email.com', 'Referral', 'contacted', '456 Park Ave', 'Delhi', 'Delhi', '110001', 'Follow up next week'],
      ['Robert Johnson', '7654321098', 'robert.j@email.com', 'Social Media', 'qualified', '789 Oak Rd', 'Bangalore', 'Karnataka', '560001', 'Budget approved'],
      ['Maria Garcia', '6543210987', 'maria.g@email.com', 'Website', 'proposal', '321 Pine St', 'Chennai', 'Tamil Nadu', '600001', 'Sent quotation'],
      ['David Kim', '5432109876', 'david.k@email.com', 'Advertisement', 'negotiation', '654 Elm St', 'Pune', 'Maharashtra', '411001', 'Discussing terms'],
      ['Sarah Wilson', '4321098765', 'sarah.w@email.com', 'Event', 'new', '987 Cedar Ln', 'Kolkata', 'West Bengal', '700001', 'Met at trade show'],
      ['Michael Brown', '3210987654', 'michael.b@email.com', 'Website', 'contacted', '147 Birch St', 'Ahmedabad', 'Gujarat', '380001', 'Requested brochure'],
      ['Emily Davis', '2109876543', 'emily.d@email.com', 'Referral', 'qualified', '258 Maple Dr', 'Hyderabad', 'Telangana', '500001', 'Ready to purchase'],
      ['James Wilson', '1098765432', 'james.w@email.com', 'Social Media', 'new', '369 Walnut St', 'Jaipur', 'Rajasthan', '302001', 'Just started looking'],
      ['Lisa Anderson', '1987654321', 'lisa.a@email.com', 'Website', 'proposal', '741 Spruce St', 'Lucknow', 'Uttar Pradesh', '226001', 'Price sensitive']
    ];

    // For CSV format
    if (type === 'csv') {
      const csvRows = [headers];
      csvRows.push(...sampleData.map(row => row.map(cell => 
        cell.includes(',') ? `"${cell}"` : cell
      ).join(',')));
      return csvRows.join('\n');
    }
    
    // For Excel format (semicolon delimited with quotes)
    else if (type === 'excel') {
      const excelRows = [headers.replace(/,/g, ';')];
      excelRows.push(...sampleData.map(row => 
        row.map(cell => `"${cell}"`).join(';')
      ));
      return excelRows.join('\n');
    }
    
    // For sample data with extra rows
    else if (type === 'sample') {
      const sampleRows = [headers];
      // Add 20 sample rows
      for (let i = 1; i <= 20; i++) {
        const names = ['Alex', 'Jordan', 'Taylor', 'Casey', 'Riley', 'Morgan', 'Cameron', 'Quinn', 'Avery', 'Blake'];
        const sources = ['Website', 'Referral', 'Social Media', 'Advertisement', 'Event'];
        const statuses = ['new', 'contacted', 'qualified', 'proposal', 'negotiation'];
        const cities = ['Mumbai', 'Delhi', 'Bangalore', 'Chennai', 'Kolkata', 'Pune', 'Ahmedabad', 'Hyderabad'];
        
        sampleRows.push([
          `${names[i % names.length]} ${String.fromCharCode(65 + i)}`,
          `98765${String(i).padStart(5, '0')}`,
          `lead${i}@example.com`,
          sources[i % sources.length],
          statuses[i % statuses.length],
          `${i} Sample Street`,
          cities[i % cities.length],
          'State',
          `${400000 + i}`,
          `Sample note for lead ${i}`
        ].map(cell => cell.includes(',') ? `"${cell}"` : cell).join(','));
      }
      return sampleRows.join('\n');
    }
  }, []);

  // Download template function - Now showSnackbar is already defined
  const handleDownloadTemplate = useCallback((type) => {
    try {
      let content = generateDummyCSV(type);
      let filename = '';
      let mimeType = '';

      if (type === 'csv') {
        filename = 'leads_template.csv';
        mimeType = 'text/csv';
      } else if (type === 'excel') {
        filename = 'leads_template.xls';
        mimeType = 'application/vnd.ms-excel';
      } else if (type === 'sample') {
        filename = 'sample_leads_data.csv';
        mimeType = 'text/csv';
      }

      const blob = new Blob([content], { type: mimeType });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      
      link.href = url;
      link.setAttribute('download', filename);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);

      showSnackbar(`${filename} downloaded successfully`, 'success');
    } catch (error) {
      console.error('Download error:', error);
      showSnackbar('Failed to download template', 'error');
    }
  }, [generateDummyCSV, showSnackbar]);

  // Event handlers
  const handleRemoveFile = useCallback(() => {
    setSelectedFile(null);
    if (fileInputRef.current) fileInputRef.current.value = null;
    showSnackbar("File removed", "info");
  }, [showSnackbar]);

  const addLead = useCallback(() => navigate("/add-lead"), [navigate]);

  const handleFilterChange = useCallback((e) => {
    setFilter(e.target.value);
    // You can add filter logic here if needed
  }, []);

  // Loading skeleton
  if (loading) {
    return (
      <Box sx={{ p: { xs: 2, sm: 3 } }}>
        <Grid container spacing={isMobile ? 1.5 : 2} sx={{ mb: 3 }}>
          {[1, 2, 3, 4].map((item) => (
            <Grid item xs={6} sm={6} md={3} key={item}>
              <Skeleton
                variant="rectangular"
                height={isMobile ? 90 : 120}
                sx={{ borderRadius: 3 }}
              />
            </Grid>
          ))}
        </Grid>
        {isMobile && (
          <Skeleton
            variant="rectangular"
            height={56}
            sx={{ borderRadius: 2, mb: 2 }}
          />
        )}
        <Skeleton
          variant="rectangular"
          height={isMobile ? 500 : 400}
          sx={{ borderRadius: 3, mb: 2 }}
        />
        <Skeleton variant="rectangular" height={56} sx={{ borderRadius: 2 }} />
      </Box>
    );
  }

  // Check if user has access to this page
  if (!canImportLeads) {
    return (
      <Box
        sx={{
          p: 3,
          textAlign: "center",
          minHeight: "60vh",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <Alert severity="warning" sx={{ maxWidth: 500, borderRadius: 3 }}>
          <AlertTitle>Access Restricted</AlertTitle>
          Only Incharge, Operation Lead, and Admin Panel can import leads.
          <br />
          <Typography variant="body2" sx={{ mt: 1 }}>
            Your role: <strong>{userRole || "Unknown"}</strong>
          </Typography>
          <Button
            sx={{ mt: 2 }}
            variant="contained"
            onClick={() => navigate("/dashboard")}
            style={{ backgroundColor: PRIMARY }}
          >
            Go to Dashboard
          </Button>
        </Alert>
      </Box>
    );
  }

  return (
    <Box
      sx={{
        bgcolor: "transparent",
        p: { xs: 1.5, sm: 2, md: 3 },
        pb: { xs: 8, sm: 3 },
        bgcolor: isDark ? "#050811" : "#f8fafc",
      }}
    >
      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{
          vertical: isMobile ? "top" : "bottom",
          horizontal: isMobile ? "center" : "right",
        }}
      >
        <Alert
          onClose={handleCloseSnackbar}
          severity={snackbar.severity}
          variant="filled"
          sx={{ width: "100%", borderRadius: 2, color: "#fff" }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>

      {/* Header with Gradient Background */}
      <Paper
        elevation={0}
        sx={{
          p: { xs: 2, sm: 3 },
          mb: 3,
          borderRadius: 3,
          background: isDark ? "linear-gradient(135deg, #090c17 0%, #11172a 100%)" : `linear-gradient(135deg, ${PRIMARY} 0%, ${SECONDARY} 100%)`,
          color: "#fff",
        }}
      >
        <Stack
          direction={{ xs: "column", sm: "row" }}
          spacing={2}
          justifyContent="space-between"
          alignItems={{ xs: "flex-start", sm: "center" }}
        >
          <Box>
            <Typography
              variant={isMobile ? "h6" : "h5"}
              fontWeight={700}
              gutterBottom
            >
              Import Leads
            </Typography>
            <Typography
              variant="body2"
              sx={{
                opacity: 0.9,
                fontSize: { xs: "0.75rem", sm: "0.875rem" },
              }}
            >
              Import and manage leads • Role: {getRoleConfig(userRole).label}
            </Typography>
          </Box>

          <Box sx={{ display: "flex", gap: 1 }}>
            <FormControl size="small" sx={{ minWidth: { xs: 120, sm: 140 } }}>
              <Select
                value={filter}
                onChange={handleFilterChange}
                sx={{
                  bgcolor: "rgba(255,255,255,0.2)",
                  color: "#fff",
                  borderRadius: 2,
                  height: 40,
                  "& .MuiSvgIcon-root": { color: "#fff" },
                  "& .MuiOutlinedInput-notchedOutline": {
                    borderColor: "rgba(255,255,255,0.3)",
                  },
                  "&:hover .MuiOutlinedInput-notchedOutline": {
                    borderColor: "rgba(255,255,255,0.5)",
                  },
                }}
              >
                <MenuItem value="Today">Today</MenuItem>
                <MenuItem value="Week">This Week</MenuItem>
                <MenuItem value="Month">This Month</MenuItem>
                <MenuItem value="Year">This Year</MenuItem>
              </Select>
            </FormControl>
            <Button
              startIcon={<Refresh />}
              onClick={fetchLeadsStats}
              variant="contained"
              size={isMobile ? "small" : "medium"}
              sx={{
                bgcolor: "rgba(255,255,255,0.2)",
                color: "#fff",
                borderRadius: 2,
                height: 40,
                "&:hover": { bgcolor: "rgba(255,255,255,0.3)" },
              }}
            >
              Refresh
            </Button>
          </Box>
        </Stack>
      </Paper>

      {/* Stats Cards */}
      <Grid container spacing={isMobile ? 1.5 : 2} sx={{ mb: 4 }}>
        {statsCards.map((card, index) => (
          <Grid item xs={6} sm={6} md={3} key={card.label}>
            <SummaryCard card={card} index={index} />
          </Grid>
        ))}
      </Grid>

      {/* Add Leads Section */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: 3,
          p: { xs: 2.5, sm: 4 },
          border: "1px solid",
          borderColor: isDark ? "rgba(255,255,255,0.08)" : "divider",
          bgcolor: isDark ? "#0b0e1a" : "#fff",
          color: isDark ? "#f8fafc" : "inherit",
        }}
      >
        <Stack 
          direction={{ xs: "column", sm: "row" }} 
          justifyContent="space-between" 
          alignItems={{ xs: "flex-start", sm: "center" }}
          sx={{ mb: 3 }}
        >
          <Box>
            <Typography
              variant={isMobile ? "h6" : "h5"}
              fontWeight="bold"
              color={isDark ? "#f8fafc" : "text.primary"}
              gutterBottom
            >
              Import New Leads
            </Typography>
            <Typography color={isDark ? "#94a3b8" : "text.secondary"}>
              Bulk import leads from Excel/CSV files or add manually
            </Typography>
          </Box>
          
          <TemplateDownload onDownload={handleDownloadTemplate} />
        </Stack>

        {/* Two Options: Manual Add & Bulk Import */}
        <Grid container spacing={3}>
          {/* Manual Add Option */}
          <Grid item xs={12} md={6}>
            <MobileOptionCard
              icon={<Add />}
              title="Add Single Lead"
              description="Add individual leads with detailed information"
              buttonText="Add New Lead"
              onClick={addLead}
              color={PRIMARY}
            />
          </Grid>

          {/* Bulk Import Option */}
          <Grid item xs={12} md={6}>
            <Paper
              elevation={0}
              sx={{
                p: { xs: 2.5, sm: 3 },
                borderRadius: 3,
                border: `2px dashed ${isDark ? "rgba(96,165,250,0.3)" : alpha(PRIMARY, 0.3)}`,
                bgcolor: isDark ? "#0e1220" : alpha(PRIMARY, 0.02),
                color: isDark ? "#f8fafc" : "inherit",
                textAlign: "center",
              }}
            >
              <Avatar
                sx={{
                  width: { xs: 52, sm: 60 },
                  height: { xs: 52, sm: 60 },
                  bgcolor: isDark ? "rgba(96,165,250,0.15)" : alpha(PRIMARY, 0.1),
                  color: isDark ? "#60a5fa" : PRIMARY,
                  mx: "auto",
                  mb: 2,
                }}
              >
                <CloudUpload sx={{ fontSize: { xs: 28, sm: 32 } }} />
              </Avatar>
              <Typography variant="h6" fontWeight={600} color={isDark ? "#f8fafc" : "text.primary"} gutterBottom>
                Bulk Import
              </Typography>
              <Typography
                variant="body2"
                color={isDark ? "#94a3b8" : "text.secondary"}
                sx={{ mb: 2.5 }}
              >
                Import multiple leads from Excel/CSV file
              </Typography>

              <Input
                inputRef={fileInputRef}
                type="file"
                accept=".xlsx,.csv"
                onChange={handleFileChange}
                sx={{ display: "none" }}
                id="file-upload"
              />

              {!selectedFile ? (
                <>
                  <label htmlFor="file-upload">
                    <Button
                      variant="contained"
                      component="span"
                      startIcon={<Upload />}
                      fullWidth
                      sx={{
                        bgcolor: isDark ? "#3b82f6" : PRIMARY,
                        borderRadius: 2,
                        py: 1.2,
                        "&:hover": { bgcolor: SECONDARY },
                      }}
                    >
                      Select File
                    </Button>
                  </label>
                </>
              ) : (
                <Box
                  sx={{
                    p: 2,
                    borderRadius: 2,
                    bgcolor: isDark ? "#050811" : "action.hover",
                  }}
                >
                  <Stack
                    direction="row"
                    alignItems="center"
                    justifyContent="space-between"
                    sx={{ mb: 2 }}
                  >
                    <Stack direction="row" alignItems="center" spacing={1.5}>
                      <Description sx={{ color: PRIMARY }} />
                      <Box sx={{ maxWidth: { xs: 150, sm: 200 } }}>
                        <Typography fontWeight={600} noWrap>
                          {selectedFile.name}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
                        </Typography>
                      </Box>
                    </Stack>
                    <IconButton size="small" onClick={handleRemoveFile}>
                      <Close />
                    </IconButton>
                  </Stack>
                  <Button
                    variant="contained"
                    onClick={handleImportLeads}
                    disabled={uploading}
                    fullWidth
                    sx={{
                      bgcolor: PRIMARY,
                      borderRadius: 2,
                      py: 1.2,
                      "&:hover": { bgcolor: SECONDARY },
                    }}
                    startIcon={
                      uploading ? (
                        <CircularProgress size={20} sx={{ color: "#fff" }} />
                      ) : null
                    }
                  >
                    {uploading ? "Importing..." : "Import Leads"}
                  </Button>
                </Box>
              )}
            </Paper>
          </Grid>
        </Grid>

        {/* Instructions */}
        <Box
          sx={{
            mt: 4,
            p: { xs: 2, sm: 3 },
            bgcolor: alpha(PRIMARY, 0.02),
            borderRadius: 2,
            border: "1px solid",
            borderColor: alpha(PRIMARY, 0.2),
          }}
        >
          <Typography
            variant="subtitle2"
            fontWeight={600}
            color={isDark ? "#f8fafc" : "text.primary"}
            gutterBottom
          >
            📋 Import Instructions
          </Typography>
          <Stack spacing={1.5} sx={{ pl: { xs: 0, sm: 2 } }}>
            <Typography
              variant="body2"
              sx={{ display: "flex", alignItems: "center", gap: 1 }}
            >
              <Info fontSize="small" sx={{ color: isDark ? "#60a5fa" : PRIMARY }} />
              1. Use the template with required columns:{" "}
              <strong>name, phone, email, source, status</strong>
            </Typography>
            <Typography
              variant="body2"
              sx={{ display: "flex", alignItems: "center", gap: 1 }}
            >
              <Info fontSize="small" sx={{ color: isDark ? "#60a5fa" : PRIMARY }} />
              2. Save file as <strong>.xlsx</strong> or <strong>.csv</strong>{" "}
              format
            </Typography>
            <Typography
              variant="body2"
              sx={{ display: "flex", alignItems: "center", gap: 1 }}
            >
              <Info fontSize="small" sx={{ color: isDark ? "#60a5fa" : PRIMARY }} />
              3. Maximum file size: <strong>10MB</strong>
            </Typography>
            <Typography
              variant="body2"
              sx={{ display: "flex", alignItems: "center", gap: 1 }}
            >
              <Info fontSize="small" sx={{ color: isDark ? "#60a5fa" : PRIMARY }} />
              4. Required permissions: <strong>Incharge, Operation Lead, or Admin Panel</strong>
            </Typography>
          </Stack>
        </Box>

        {/* Quick Tips */}
        <Box
          sx={{
            mt: 3,
            p: { xs: 1.5, sm: 2 },
            bgcolor: alpha(PRIMARY, 0.08),
            borderRadius: 2,
            border: "1px solid",
            borderColor: alpha(PRIMARY, 0.3),
          }}
        >
          <Stack direction="row" spacing={1} alignItems="center">
            <Warning sx={{ color: isDark ? "#60a5fa" : PRIMARY, fontSize: { xs: 18, sm: 20 } }} />
            <Typography variant="body2">
              <strong>Tip:</strong> Ensure phone numbers are in correct format
              (10 digits). Invalid data may be skipped during import.
            </Typography>
          </Stack>
        </Box>
      </Paper>
    </Box>
  );
}
